-- ============================================================
--  FINAPP v2 — Schema refatorado
--  PostgreSQL 14+
--
--  MUDANÇAS vs v1:
--    • IDs: UUID → BIGINT GENERATED BY DEFAULT AS IDENTITY
--    • Toda tabela possui [tabela]_code VARCHAR(6) UNIQUE
--    • Chaves primárias compostas: (id_[tabela], [tabela]_code)
--    • FKs compostas em todas as referências
--    • categorias: removidos categoria_pai_id e usuario_id
--    • NOVA: categorias_pai       — hierarquia pai/filho
--    • NOVA: categorias_do_usuario — vínculo usuario ↔ categoria
--    • NOVA: motivos_cancelamento  — catálogo de motivos
--    • NOVA: transacoes_canceladas — log de cancelamentos
--    • REMOVIDAS: classificacao_logs, regras_classificacao
-- ============================================================

-- ─────────────────────────────────────────────
-- 0. EXTENSÕES + FUNÇÃO GERADORA DE CODE
-- ─────────────────────────────────────────────
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "citext";

-- Gera um código alfanumérico maiúsculo de 6 caracteres
-- Usado como DEFAULT em todos os campos [tabela]_code
CREATE OR REPLACE FUNCTION generate_code()
RETURNS VARCHAR(6)
LANGUAGE sql
VOLATILE
AS $$
  SELECT upper(
    substring(
      md5(random()::text || clock_timestamp()::text),
      1, 6
    )
  );
$$;


-- ─────────────────────────────────────────────
-- SEQUÊNCIA COMPARTILHADA — auditoria_eventos
-- (tabela particionada não suporta IDENTITY nativo)
-- ─────────────────────────────────────────────
CREATE SEQUENCE IF NOT EXISTS auditoria_eventos_id_seq AS BIGINT;

-- Sequência para correlation_id — identifica um fluxo distribuído de ponta a ponta.
-- Cada requisição/operação gera um nextval único; todos os eventos do mesmo fluxo
-- compartilham o mesmo correlation_id, permitindo rastreio entre microsserviços.
CREATE SEQUENCE IF NOT EXISTS correlation_id_seq AS BIGINT;


-- ═══════════════════════════════════════════════════════════════
--  TABELAS
-- ═══════════════════════════════════════════════════════════════

-- ─────────────────────────────────────────────
-- 1. parser_versoes
-- ─────────────────────────────────────────────
CREATE TABLE parser_versoes (
    id_parser_versoes    BIGINT       GENERATED BY DEFAULT AS IDENTITY,
    parser_versoes_code  VARCHAR(6)   NOT NULL UNIQUE DEFAULT generate_code(),
    banco                VARCHAR(100) NOT NULL,
    versao               VARCHAR(20)  NOT NULL,
    ativo                BOOLEAN      NOT NULL DEFAULT TRUE,
    score_qualidade      NUMERIC(4,3),
    total_usos           INT          NOT NULL DEFAULT 0,
    total_erros          INT          NOT NULL DEFAULT 0,
    descricao            TEXT,
    depreciado_em        TIMESTAMPTZ,
    CONSTRAINT pk_parser_versoes     PRIMARY KEY (id_parser_versoes, parser_versoes_code),
    CONSTRAINT uq_parser_banco_versao UNIQUE (banco, versao)
);


-- ─────────────────────────────────────────────
-- 2. usuarios
-- ─────────────────────────────────────────────
CREATE TABLE usuarios (
    id_usuarios              BIGINT       GENERATED BY DEFAULT AS IDENTITY,
    usuarios_code            VARCHAR(6)   NOT NULL UNIQUE DEFAULT generate_code(),
    -- identificador de negócio legível (FIN-XXXXXX)
    codigo                   VARCHAR(12)  UNIQUE NOT NULL,
    cpf                      VARCHAR(255) NOT NULL,             -- AES-256 em repouso
    cpf_hash                 VARCHAR(64)  UNIQUE,               -- SHA-256 para lookup
    nome_completo            VARCHAR(150) NOT NULL,
    email                    VARCHAR(255) UNIQUE NOT NULL,
    senha_hash               VARCHAR(255) NOT NULL,             -- bcrypt
    telefone                 VARCHAR(20),
    telegram_chat_id         BIGINT,
    whatsapp_id              VARCHAR(100),
    saldo_inicial_definido   BOOLEAN      NOT NULL DEFAULT FALSE,
    moeda                    CHAR(3)      NOT NULL DEFAULT 'BRL',
    ativo                    BOOLEAN      NOT NULL DEFAULT TRUE,
    email_verificado         BOOLEAN      NOT NULL DEFAULT FALSE,
    token_verificacao        VARCHAR(100),
    token_verificacao_expira TIMESTAMPTZ,
    ultimo_login             TIMESTAMPTZ,
    tentativas_login         SMALLINT     NOT NULL DEFAULT 0,
    bloqueado_ate            TIMESTAMPTZ,
    refresh_token_hash       VARCHAR(255),
    api_key_hash             VARCHAR(255),
    deleted_at               TIMESTAMPTZ,
    versao                   INT          NOT NULL DEFAULT 1,
    criado_em                TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    atualizado_em            TIMESTAMPTZ,
    CONSTRAINT pk_usuarios PRIMARY KEY (id_usuarios, usuarios_code)
);


-- ─────────────────────────────────────────────
-- 3. contas_financeiras
-- ─────────────────────────────────────────────
CREATE TABLE contas_financeiras (
    id_contas_financeiras   BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    contas_financeiras_code VARCHAR(6)    NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → usuarios
    usuario_id              BIGINT        NOT NULL,
    usuario_code            VARCHAR(6)    NOT NULL,
    nome                    VARCHAR(100)  NOT NULL,
    tipo                    VARCHAR(20)   NOT NULL
                                CHECK (tipo IN ('corrente','poupanca','cartao','dinheiro','investimento')),
    banco                   VARCHAR(100),
    saldo_inicial           NUMERIC(15,2) NOT NULL DEFAULT 0,
    padrao                  BOOLEAN       DEFAULT FALSE,
    ativa                   BOOLEAN       DEFAULT TRUE,
    criado_em               TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    atualizado_em           TIMESTAMPTZ,
    CONSTRAINT pk_contas_financeiras PRIMARY KEY (id_contas_financeiras, contas_financeiras_code),
    CONSTRAINT fk_contas_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code)
        ON DELETE CASCADE
);


-- ─────────────────────────────────────────────
-- 4. categorias
--    • SEM categoria_pai_id  → ver categorias_pai
--    • SEM usuario_id        → ver categorias_do_usuario
-- ─────────────────────────────────────────────
CREATE TABLE categorias (
    id_categorias    BIGINT       GENERATED BY DEFAULT AS IDENTITY,
    categorias_code  VARCHAR(6)   NOT NULL UNIQUE DEFAULT generate_code(),
    nome             VARCHAR(100) NOT NULL,
    tipo             VARCHAR(10)  NOT NULL CHECK (tipo IN ('receita','gasto','ambos')),
    icone            VARCHAR(50),
    cor_hex          CHAR(7),
    padrao           BOOLEAN      DEFAULT FALSE,  -- TRUE = categoria global imutável
    criado_em        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT pk_categorias PRIMARY KEY (id_categorias, categorias_code)
);


-- ─────────────────────────────────────────────
-- 5. categorias_pai
--    Tabela de hierarquia: registra qual categoria é pai de outra.
--    Uma categoria pode ter apenas 1 pai (relação muitos-para-um).
-- ─────────────────────────────────────────────
CREATE TABLE categorias_pai (
    id_categorias_pai    BIGINT     GENERATED BY DEFAULT AS IDENTITY,
    categorias_pai_code  VARCHAR(6) NOT NULL UNIQUE DEFAULT generate_code(),
    -- categoria filha
    categoria_id         BIGINT     NOT NULL,
    categoria_code       VARCHAR(6) NOT NULL,
    -- categoria pai
    pai_id               BIGINT     NOT NULL,
    pai_code             VARCHAR(6) NOT NULL,
    criado_em            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT pk_categorias_pai PRIMARY KEY (id_categorias_pai, categorias_pai_code),
    CONSTRAINT fk_catpai_filho
        FOREIGN KEY (categoria_id, categoria_code)
        REFERENCES categorias(id_categorias, categorias_code)
        ON DELETE CASCADE,
    CONSTRAINT fk_catpai_pai
        FOREIGN KEY (pai_id, pai_code)
        REFERENCES categorias(id_categorias, categorias_code)
        ON DELETE CASCADE,
    -- uma categoria só pode ter um pai
    CONSTRAINT uq_catpai_filho UNIQUE (categoria_id, categoria_code),
    -- evita auto-referência
    CONSTRAINT ck_catpai_no_self CHECK (categoria_id <> pai_id)
);


-- ─────────────────────────────────────────────
-- 6. categorias_do_usuario
--    Tabela de vínculo entre usuário e categorias.
--    Inclui tanto as globais visíveis quanto as criadas pelo usuário.
-- ─────────────────────────────────────────────
CREATE TABLE categorias_do_usuario (
    id_categorias_do_usuario    BIGINT      GENERATED BY DEFAULT AS IDENTITY,
    categorias_do_usuario_code  VARCHAR(6)  NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → usuarios
    usuario_id                  BIGINT      NOT NULL,
    usuario_code                VARCHAR(6)  NOT NULL,
    -- FK composta → categorias
    categoria_id                BIGINT      NOT NULL,
    categoria_code              VARCHAR(6)  NOT NULL,
    ativa                       BOOLEAN     NOT NULL DEFAULT TRUE,
    criado_em                   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT pk_cat_usuario PRIMARY KEY (id_categorias_do_usuario, categorias_do_usuario_code),
    CONSTRAINT fk_catuser_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code)
        ON DELETE CASCADE,
    CONSTRAINT fk_catuser_categoria
        FOREIGN KEY (categoria_id, categoria_code)
        REFERENCES categorias(id_categorias, categorias_code)
        ON DELETE CASCADE,
    -- cada categoria aparece uma única vez por usuário
    CONSTRAINT uq_catuser_par UNIQUE (usuario_id, usuario_code, categoria_id, categoria_code)
);


-- ─────────────────────────────────────────────
-- 7. categoria_thresholds
-- ─────────────────────────────────────────────
CREATE TABLE categoria_thresholds (
    id_categoria_thresholds    BIGINT     GENERATED BY DEFAULT AS IDENTITY,
    categoria_thresholds_code  VARCHAR(6) NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → categorias
    categoria_id               BIGINT     NOT NULL,
    categoria_code             VARCHAR(6) NOT NULL,
    threshold_auto             SMALLINT   NOT NULL DEFAULT 70  CHECK (threshold_auto   BETWEEN 0 AND 100),
    threshold_alerta           SMALLINT   NOT NULL DEFAULT 50  CHECK (threshold_alerta BETWEEN 0 AND 100),
    ambiguidade_alta           BOOLEAN    NOT NULL DEFAULT FALSE,
    CONSTRAINT pk_cat_thresholds PRIMARY KEY (id_categoria_thresholds, categoria_thresholds_code),
    CONSTRAINT fk_catthresh_categoria
        FOREIGN KEY (categoria_id, categoria_code)
        REFERENCES categorias(id_categorias, categorias_code)
        ON DELETE CASCADE,
    -- um threshold por categoria
    CONSTRAINT uq_catthresh_cat UNIQUE (categoria_id, categoria_code)
);


-- ─────────────────────────────────────────────
-- 8. extratos
-- ─────────────────────────────────────────────
CREATE TABLE extratos (
    id_extratos                  BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    extratos_code                VARCHAR(6)    NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → usuarios
    usuario_id                   BIGINT        NOT NULL,
    usuario_code                 VARCHAR(6)    NOT NULL,
    -- FK composta → contas_financeiras
    conta_id                     BIGINT        NOT NULL,
    conta_code                   VARCHAR(6)    NOT NULL,
    arquivo_nome                 VARCHAR(255),
    arquivo_uuid                 VARCHAR(255)  NOT NULL,
    hash_arquivo                 VARCHAR(64)   NOT NULL,
    banco_detectado              VARCHAR(100),
    -- FK composta → parser_versoes (nullable)
    parser_versao_id             BIGINT,
    parser_versao_code           VARCHAR(6),
    score_extracao               NUMERIC(4,3),
    periodo_inicio               DATE,
    periodo_fim                  DATE,
    status                       VARCHAR(30)   NOT NULL DEFAULT 'upload_recebido'
                                     CHECK (status IN (
                                         'upload_recebido','validando','na_fila','extraindo',
                                         'classificando','aguardando_ia','pendente_revisao',
                                         'parcialmente_revisado','concluido','erro_formato',
                                         'erro_extracao','erro_classificacao','erro_timeout',
                                         'cancelado','reprocessando'
                                     )),
    total_lancamentos            INT           NOT NULL DEFAULT 0,
    lancamentos_confirmados      INT           NOT NULL DEFAULT 0,
    lancamentos_pendentes        INT           NOT NULL DEFAULT 0,
    lancamentos_ignorados        INT           NOT NULL DEFAULT 0,
    versao                       INT           NOT NULL DEFAULT 1,
    criado_em                    TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    atualizado_em                TIMESTAMPTZ,
    CONSTRAINT pk_extratos PRIMARY KEY (id_extratos, extratos_code),
    CONSTRAINT fk_extratos_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code)
        ON DELETE CASCADE,
    CONSTRAINT fk_extratos_conta
        FOREIGN KEY (conta_id, conta_code)
        REFERENCES contas_financeiras(id_contas_financeiras, contas_financeiras_code),
    CONSTRAINT fk_extratos_parser
        FOREIGN KEY (parser_versao_id, parser_versao_code)
        REFERENCES parser_versoes(id_parser_versoes, parser_versoes_code)
);


-- ─────────────────────────────────────────────
-- 9. transacoes
-- ─────────────────────────────────────────────
CREATE TABLE transacoes (
    id_transacoes              BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    transacoes_code            VARCHAR(6)    NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → usuarios
    usuario_id                 BIGINT        NOT NULL,
    usuario_code               VARCHAR(6)    NOT NULL,
    -- FK composta → contas_financeiras
    conta_id                   BIGINT        NOT NULL,
    conta_code                 VARCHAR(6)    NOT NULL,
    -- FK composta → extratos (nullable)
    extrato_id                 BIGINT,
    extrato_code               VARCHAR(6),
    -- auto-referência para estorno (nullable)
    transacao_estorno_id       BIGINT,
    transacao_estorno_code     VARCHAR(6),
    tipo                       VARCHAR(10)   NOT NULL CHECK (tipo IN ('receita','gasto')),
    descricao_original         TEXT,
    descricao_usuario          VARCHAR(255),
    descricao_normalizada      VARCHAR(255),
    valor                      NUMERIC(15,2) NOT NULL CHECK (valor > 0),
    data_transacao             DATE          NOT NULL,
    data_lancamento            TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    -- FK composta → categorias (nullable)
    categoria_id               BIGINT,
    categoria_code             VARCHAR(6),
    subcategoria               VARCHAR(100),
    estabelecimento            VARCHAR(255),
    origem                     VARCHAR(20)   NOT NULL DEFAULT 'manual'
                                   CHECK (origem IN ('manual','pdf','api')),
    status_revisao             VARCHAR(30)   NOT NULL DEFAULT 'extraida'
                                   CHECK (status_revisao IN (
                                       'extraida','classificada','pendente_revisao',
                                       'confirmada','ignorada','arquivada'
                                   )),
    confianca_ia               SMALLINT      CHECK (confianca_ia BETWEEN 0 AND 100),
    recorrente                 BOOLEAN       DEFAULT FALSE,
    periodo_recorrencia        VARCHAR(20),
    observacao                 TEXT,
    deleted_at                 TIMESTAMPTZ,
    versao                     INT           NOT NULL DEFAULT 1,
    criado_em                  TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    atualizado_em              TIMESTAMPTZ,
    CONSTRAINT pk_transacoes PRIMARY KEY (id_transacoes, transacoes_code),
    CONSTRAINT fk_transacoes_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code)
        ON DELETE CASCADE,
    CONSTRAINT fk_transacoes_conta
        FOREIGN KEY (conta_id, conta_code)
        REFERENCES contas_financeiras(id_contas_financeiras, contas_financeiras_code),
    CONSTRAINT fk_transacoes_extrato
        FOREIGN KEY (extrato_id, extrato_code)
        REFERENCES extratos(id_extratos, extratos_code),
    CONSTRAINT fk_transacoes_estorno
        FOREIGN KEY (transacao_estorno_id, transacao_estorno_code)
        REFERENCES transacoes(id_transacoes, transacoes_code),
    CONSTRAINT fk_transacoes_categoria
        FOREIGN KEY (categoria_id, categoria_code)
        REFERENCES categorias(id_categorias, categorias_code)
);


-- ─────────────────────────────────────────────
-- 10. motivos_cancelamento
--     Catálogo de motivos pelo qual uma transação pode ser cancelada.
-- ─────────────────────────────────────────────
CREATE TABLE motivos_cancelamento (
    id_motivos_cancelamento    BIGINT       GENERATED BY DEFAULT AS IDENTITY,
    motivos_cancelamento_code  VARCHAR(6)   NOT NULL UNIQUE DEFAULT generate_code(),
    descricao                  VARCHAR(255) NOT NULL,
    -- quem pode acionar este motivo
    origem_permitida           VARCHAR(20)  NOT NULL DEFAULT 'todos'
                                   CHECK (origem_permitida IN ('usuario','sistema','admin','todos')),
    ativo                      BOOLEAN      NOT NULL DEFAULT TRUE,
    criado_em                  TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    CONSTRAINT pk_motivos_cancelamento PRIMARY KEY (id_motivos_cancelamento, motivos_cancelamento_code)
);


-- ─────────────────────────────────────────────
-- 11. transacoes_canceladas
--     Registra cada cancelamento de transação com rastreabilidade
--     completa: quem cancelou, por qual motivo e quando.
--     A transação original recebe deleted_at = NOW() ao ser cancelada.
-- ─────────────────────────────────────────────
CREATE TABLE transacoes_canceladas (
    id_transacoes_canceladas    BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    transacoes_canceladas_code  VARCHAR(6)    NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → transacoes (a transação que foi cancelada)
    transacao_id                BIGINT        NOT NULL,
    transacao_code              VARCHAR(6)    NOT NULL,
    -- FK composta → usuarios
    usuario_id                  BIGINT        NOT NULL,
    usuario_code                VARCHAR(6)    NOT NULL,
    -- FK composta → contas_financeiras
    conta_id                    BIGINT        NOT NULL,
    conta_code                  VARCHAR(6)    NOT NULL,
    -- FK composta → motivos_cancelamento
    motivo_id                   BIGINT        NOT NULL,
    motivo_code                 VARCHAR(6)    NOT NULL,
    -- quem executou o cancelamento
    cancelado_por               VARCHAR(20)   NOT NULL DEFAULT 'usuario'
                                    CHECK (cancelado_por IN ('usuario','sistema','admin')),
    valor_original              NUMERIC(15,2) NOT NULL,   -- cópia do valor no momento do cancelamento
    observacao                  TEXT,
    ip_origem                   INET,
    cancelado_em                TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    -- uma transação só pode ser cancelada uma vez
    CONSTRAINT pk_transacoes_canceladas PRIMARY KEY (id_transacoes_canceladas, transacoes_canceladas_code),
    CONSTRAINT fk_txcanc_transacao
        FOREIGN KEY (transacao_id, transacao_code)
        REFERENCES transacoes(id_transacoes, transacoes_code),
    CONSTRAINT fk_txcanc_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code),
    CONSTRAINT fk_txcanc_conta
        FOREIGN KEY (conta_id, conta_code)
        REFERENCES contas_financeiras(id_contas_financeiras, contas_financeiras_code),
    CONSTRAINT fk_txcanc_motivo
        FOREIGN KEY (motivo_id, motivo_code)
        REFERENCES motivos_cancelamento(id_motivos_cancelamento, motivos_cancelamento_code),
    CONSTRAINT uq_txcanc_transacao UNIQUE (transacao_id, transacao_code)
);


-- ─────────────────────────────────────────────
-- 12. processamento_jobs
-- ─────────────────────────────────────────────
CREATE TABLE processamento_jobs (
    id_processamento_jobs    BIGINT      GENERATED BY DEFAULT AS IDENTITY,
    processamento_jobs_code  VARCHAR(6)  NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → extratos (nullable)
    extrato_id               BIGINT,
    extrato_code             VARCHAR(6),
    tipo                     VARCHAR(30) NOT NULL CHECK (tipo IN (
                                 'extracao_pdf','classificacao_ia','notificacao',
                                 'geracao_pdf','snapshot','anonimizacao'
                             )),
    status                   VARCHAR(30) NOT NULL DEFAULT 'enfileirado' CHECK (status IN (
                                 'enfileirado','iniciando','processando','aguardando_ia',
                                 'concluido','falha_ia','falha_parser','timeout',
                                 'retry_1','retry_2','retry_3','dead_letter','cancelado'
                             )),
    tentativas               SMALLINT    NOT NULL DEFAULT 0,
    max_tentativas           SMALLINT    NOT NULL DEFAULT 3,
    payload                  JSONB,
    erro_mensagem            TEXT,
    worker_id                VARCHAR(100),
    lock_expires_at          TIMESTAMPTZ,
    correlation_id           BIGINT,        -- rastreabilidade distribuída — nextval(correlation_id_seq)
    enfileirado_em           TIMESTAMPTZ    NOT NULL DEFAULT NOW(),
    iniciado_em              TIMESTAMPTZ,
    concluido_em             TIMESTAMPTZ,
    proximo_retry            TIMESTAMPTZ,
    CONSTRAINT pk_processamento_jobs PRIMARY KEY (id_processamento_jobs, processamento_jobs_code),
    CONSTRAINT fk_jobs_extrato
        FOREIGN KEY (extrato_id, extrato_code)
        REFERENCES extratos(id_extratos, extratos_code)
);


-- ─────────────────────────────────────────────
-- 13. snapshots_financeiros
-- ─────────────────────────────────────────────
CREATE TABLE snapshots_financeiros (
    id_snapshots_financeiros    BIGINT        GENERATED BY DEFAULT AS IDENTITY,
    snapshots_financeiros_code  VARCHAR(6)    NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → usuarios
    usuario_id                  BIGINT        NOT NULL,
    usuario_code                VARCHAR(6)    NOT NULL,
    -- FK composta → contas_financeiras (NULL = consolidado de todas as contas)
    conta_id                    BIGINT,
    conta_code                  VARCHAR(6),
    ano                         SMALLINT      NOT NULL,
    mes                         SMALLINT      NOT NULL CHECK (mes BETWEEN 1 AND 12),
    saldo_inicial               NUMERIC(15,2) NOT NULL,
    total_receitas              NUMERIC(15,2) NOT NULL DEFAULT 0,
    total_gastos                NUMERIC(15,2) NOT NULL DEFAULT 0,
    saldo_final                 NUMERIC(15,2) NOT NULL,
    fechado                     BOOLEAN       NOT NULL DEFAULT FALSE,
    fechado_em                  TIMESTAMPTZ,
    CONSTRAINT pk_snapshots_financeiros PRIMARY KEY (id_snapshots_financeiros, snapshots_financeiros_code),
    CONSTRAINT fk_snap_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code)
        ON DELETE CASCADE,
    CONSTRAINT fk_snap_conta
        FOREIGN KEY (conta_id, conta_code)
        REFERENCES contas_financeiras(id_contas_financeiras, contas_financeiras_code)
);

-- Unicidade para snapshots com conta específica
CREATE UNIQUE INDEX uq_snapshot_com_conta
    ON snapshots_financeiros(usuario_id, conta_id, ano, mes)
    WHERE conta_id IS NOT NULL;

-- Unicidade para snapshot consolidado (conta NULL)
CREATE UNIQUE INDEX uq_snapshot_consolidado
    ON snapshots_financeiros(usuario_id, ano, mes)
    WHERE conta_id IS NULL;


-- ─────────────────────────────────────────────
-- 14. auditoria_eventos (tabela particionada por mês)
--     Usa sequência explícita pois IDENTITY não é suportado
--     diretamente em tabelas particionadas no PG 14.
--     A PK inclui criado_em (chave de partição — obrigatório).
--     IMUTÁVEL: nunca recebe UPDATE ou DELETE.
-- ─────────────────────────────────────────────
CREATE TABLE auditoria_eventos (
    id_auditoria_eventos    BIGINT      NOT NULL DEFAULT nextval('auditoria_eventos_id_seq'),
    auditoria_eventos_code  VARCHAR(6)  NOT NULL DEFAULT generate_code(),
    correlation_id          BIGINT      NOT NULL,           -- rastreabilidade distribuída — nextval(correlation_id_seq)
    -- FK composta → usuarios (nullable — eventos de sistema)
    usuario_id              BIGINT,
    usuario_code            VARCHAR(6),
    entidade                VARCHAR(50) NOT NULL,           -- ex: 'transacao', 'extrato'
    entidade_id             BIGINT      NOT NULL,           -- ID da entidade auditada
    acao                    VARCHAR(30) NOT NULL CHECK (acao IN (
                                'CREATE','UPDATE','DELETE','LOGIN','LOGOUT','UPLOAD',
                                'CLASSIFY','CONFIRM','REJECT','EXPORT','REPROCESS',
                                'API_KEY_GEN','PASSWORD_CHANGE','CANCEL'
                            )),
    dados_anteriores        JSONB,      -- snapshot before (NUNCA incluir CPF/senha/tokens)
    dados_novos             JSONB,      -- snapshot after
    ip_origem               INET,       -- último octeto mascarado
    user_agent              TEXT,
    origem                  VARCHAR(20) CHECK (origem IN ('web','bot_whatsapp','bot_telegram','api','sistema')),
    criado_em               TIMESTAMPTZ NOT NULL DEFAULT NOW(),   -- IMUTÁVEL
    CONSTRAINT pk_auditoria_eventos PRIMARY KEY (id_auditoria_eventos, auditoria_eventos_code, criado_em),
    CONSTRAINT fk_audit_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code)
) PARTITION BY RANGE (criado_em);

