-- ─────────────────────────────────────────────
-- 15. consentimentos_lgpd
-- ─────────────────────────────────────────────
CREATE TABLE consentimentos_lgpd (
    id_consentimentos_lgpd    BIGINT      GENERATED BY DEFAULT AS IDENTITY,
    consentimentos_lgpd_code  VARCHAR(6)  NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → usuarios
    usuario_id                BIGINT      NOT NULL,
    usuario_code              VARCHAR(6)  NOT NULL,
    tipo                      VARCHAR(50) NOT NULL CHECK (tipo IN (
                                  'tratamento_dados_financeiros','uso_ia',
                                  'armazenamento_extrato','bot_whatsapp','bot_telegram'
                              )),
    versao_politica           VARCHAR(20) NOT NULL,
    consentido                BOOLEAN     NOT NULL,
    ip_origem                 INET,
    criado_em                 TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    revogado_em               TIMESTAMPTZ,
    revogado_motivo           TEXT,
    CONSTRAINT pk_consentimentos_lgpd PRIMARY KEY (id_consentimentos_lgpd, consentimentos_lgpd_code),
    CONSTRAINT fk_lgpd_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code)
        ON DELETE CASCADE
);


-- ─────────────────────────────────────────────
-- 16. notificacoes
-- ─────────────────────────────────────────────
CREATE TABLE notificacoes (
    id_notificacoes    BIGINT      GENERATED BY DEFAULT AS IDENTITY,
    notificacoes_code  VARCHAR(6)  NOT NULL UNIQUE DEFAULT generate_code(),
    -- FK composta → usuarios
    usuario_id         BIGINT      NOT NULL,
    usuario_code       VARCHAR(6)  NOT NULL,
    canal              VARCHAR(20) NOT NULL CHECK (canal IN ('whatsapp','telegram','email')),
    tipo               VARCHAR(50) NOT NULL,
    titulo             VARCHAR(255),
    mensagem           TEXT,
    enviada            BOOLEAN     NOT NULL DEFAULT FALSE,
    enviada_em         TIMESTAMPTZ,
    erro               TEXT,
    tentativas         SMALLINT    NOT NULL DEFAULT 0,
    criado_em          TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT pk_notificacoes PRIMARY KEY (id_notificacoes, notificacoes_code),
    CONSTRAINT fk_notif_usuario
        FOREIGN KEY (usuario_id, usuario_code)
        REFERENCES usuarios(id_usuarios, usuarios_code)
        ON DELETE CASCADE
);


-- ═══════════════════════════════════════════════════════════════
--  ÍNDICES
-- ═══════════════════════════════════════════════════════════════

-- usuarios
CREATE INDEX idx_usuarios_email     ON usuarios(email)    WHERE deleted_at IS NULL;
CREATE INDEX idx_usuarios_cpf_hash  ON usuarios(cpf_hash) WHERE deleted_at IS NULL;
CREATE INDEX idx_usuarios_codigo    ON usuarios(codigo);

-- contas_financeiras
CREATE INDEX idx_contas_usuario     ON contas_financeiras(usuario_id);

-- categorias
CREATE INDEX idx_categorias_tipo    ON categorias(tipo);
CREATE INDEX idx_categorias_padrao  ON categorias(padrao) WHERE padrao = TRUE;

-- categorias_do_usuario
CREATE INDEX idx_catuser_usuario    ON categorias_do_usuario(usuario_id);
CREATE INDEX idx_catuser_categoria  ON categorias_do_usuario(categoria_id);

-- categorias_pai
CREATE INDEX idx_catpai_filho       ON categorias_pai(categoria_id);
CREATE INDEX idx_catpai_pai         ON categorias_pai(pai_id);

-- extratos
CREATE INDEX idx_extratos_usuario   ON extratos(usuario_id, criado_em DESC);
CREATE INDEX idx_extratos_hash      ON extratos(hash_arquivo);

-- transacoes
CREATE INDEX idx_transacoes_usuario ON transacoes(usuario_id, data_transacao DESC) WHERE deleted_at IS NULL;
CREATE INDEX idx_transacoes_conta   ON transacoes(conta_id);
CREATE INDEX idx_transacoes_cat     ON transacoes(categoria_id);
CREATE INDEX idx_transacoes_status  ON transacoes(status_revisao);
CREATE INDEX idx_transacoes_extrato ON transacoes(extrato_id) WHERE extrato_id IS NOT NULL;

-- transacoes_canceladas
CREATE INDEX idx_txcanc_transacao   ON transacoes_canceladas(transacao_id);
CREATE INDEX idx_txcanc_usuario     ON transacoes_canceladas(usuario_id);
CREATE INDEX idx_txcanc_motivo      ON transacoes_canceladas(motivo_id);

-- snapshots
CREATE INDEX idx_snap_usuario_mes   ON snapshots_financeiros(usuario_id, ano DESC, mes DESC);

-- auditoria_eventos (herdado pelas partições)
CREATE INDEX idx_audit_usuario      ON auditoria_eventos(usuario_id, criado_em DESC);
CREATE INDEX idx_audit_correlation  ON auditoria_eventos(correlation_id);
CREATE INDEX idx_audit_entidade     ON auditoria_eventos(entidade, entidade_id);


