-- ═══════════════════════════════════════════════════════════════
--  SEED — USUÁRIO DE DEMONSTRAÇÃO + dados relacionados
-- ═══════════════════════════════════════════════════════════════
-- ATENÇÃO:
--   • senha_hash é placeholder bcrypt — substitua via API em produção
--   • CPF é fictício sem criptografia real — use AES-256 na aplicação

DO $$
DECLARE
  -- usuário
  v_usr_id    BIGINT;  v_usr_code    VARCHAR(6);

  -- contas
  v_nub_id    BIGINT;  v_nub_code    VARCHAR(6);
  v_ita_id    BIGINT;  v_ita_code    VARCHAR(6);
  v_car_id    BIGINT;  v_car_code    VARCHAR(6);

  -- extrato
  v_ext_id    BIGINT;  v_ext_code    VARCHAR(6);

  -- parser
  v_par_id    BIGINT;  v_par_code    VARCHAR(6);

  -- transação amazon (será cancelada)
  v_amz_id    BIGINT;  v_amz_code    VARCHAR(6);
  v_amz_val   NUMERIC(15,2) := 215.00;

  -- motivo cancelamento
  v_mot_id    BIGINT;  v_mot_code    VARCHAR(6);

  v_corr      BIGINT;

BEGIN

  -- ── Parser Nubank ─────────────────────────────────────────
  -- Gera o correlation_id para rastrear todo este fluxo de seed
  v_corr := nextval('correlation_id_seq');

  SELECT id_parser_versoes, parser_versoes_code
    INTO v_par_id, v_par_code
    FROM parser_versoes WHERE banco = 'Nubank' AND versao = 'v1.0';

  -- ── Motivo cancelamento (Cancelado pelo usuário) ───────────
  SELECT id_motivos_cancelamento, motivos_cancelamento_code
    INTO v_mot_id, v_mot_code
    FROM motivos_cancelamento WHERE id_motivos_cancelamento = 5;

  -- ── Usuário ───────────────────────────────────────────────
  INSERT INTO usuarios (
    codigo, cpf, cpf_hash, nome_completo, email, senha_hash,
    telefone, saldo_inicial_definido, moeda, ativo, email_verificado,
    ultimo_login, versao
  ) VALUES (
    'FIN-DEMO01',
    'ENCRYPTED_CPF_PLACEHOLDER',
    encode(sha256('12345678909'::bytea), 'hex'),
    'João Silva Demonstração',
    'joao.demo@finapp.com.br',
    '$2b$12$K2hXdW7eL9mNqRvP3sBuCeXgTlAaDz5yQfJcMkwE1nHoVpYrI8uGa',
    '(11) 99999-0000',
    TRUE, 'BRL', TRUE, TRUE,
    NOW(), 1
  )
  RETURNING id_usuarios, usuarios_code INTO v_usr_id, v_usr_code;

  -- ── Consentimentos LGPD ───────────────────────────────────
  INSERT INTO consentimentos_lgpd
    (usuario_id, usuario_code, tipo, versao_politica, consentido, ip_origem)
  VALUES
    (v_usr_id, v_usr_code, 'tratamento_dados_financeiros', '1.0', TRUE, '192.0.2.1'),
